contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test transferFrom behavior for shares: caller is this contract (msg.sender when calling c)
    // Params: from - source address that must have enough shares; spender - this contract must be approved
    // amount - amount to transfer
    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0), "invalid addr");

        // Observe balances and allowance before
        uint256 fromBalBefore = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 toBalBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 allowanceBefore = c.allowance(from, address(this)); if (__ESBMC_reverted()) return;

        // Call transferFrom and catch revert
        bool reverted = false;
        bool ok = c.transferFrom(from, to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 fromBalAfter = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 toBalAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 allowanceAfter = c.allowance(from, address(this)); if (__ESBMC_reverted()) return;

        // General rule:
        // If transferFrom reverted then balances and allowance unchanged.
        // If it succeeded then: from balance decreased by exactly amount, to balance increased by exactly amount,
        // and allowance decreased by exactly amount (but not below zero) unless allowanceBefore was type(uint256).max (infinite allowance), in which case allowance stays unchanged.
        assert(
            (reverted && fromBalAfter == fromBalBefore && toBalAfter == toBalBefore && allowanceAfter == allowanceBefore)
            || (!reverted && fromBalAfter + amount == fromBalBefore && toBalAfter == toBalBefore + amount &&
                (allowanceBefore == type(uint256).max ? allowanceAfter == allowanceBefore : allowanceAfter + amount == allowanceBefore))
        );
    }

    receive() external payable {}
}

