// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(address from, address to, uint256 amount) internal {
        vm.assume(from != address(0) && to != address(0));
        uint256 fromBalBefore;
        try c.balanceOf(from) returns (uint256 __r) { fromBalBefore = __r; } catch { return; }
        uint256 toBalBefore;
        try c.balanceOf(to) returns (uint256 __r) { toBalBefore = __r; } catch { return; }
        uint256 allowanceBefore;
        try c.allowance(from, address(this)) returns (uint256 __r) { allowanceBefore = __r; } catch { return; }
        bool reverted = false;
        try c.transferFrom(from, to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 fromBalAfter;
        try c.balanceOf(from) returns (uint256 __r) { fromBalAfter = __r; } catch { return; }
        uint256 toBalAfter;
        try c.balanceOf(to) returns (uint256 __r) { toBalAfter = __r; } catch { return; }
        uint256 allowanceAfter;
        try c.allowance(from, address(this)) returns (uint256 __r) { allowanceAfter = __r; } catch { return; }
        assertTrue((reverted && fromBalAfter == fromBalBefore && toBalAfter == toBalBefore && allowanceAfter == allowanceBefore)
            || (!reverted && fromBalAfter + amount == fromBalBefore && toBalAfter == toBalBefore + amount &&
                (allowanceBefore == type(uint256).max ? allowanceAfter == allowanceBefore : allowanceAfter + amount == allowanceBefore)));
    }

    function testFuzz_run(address from, address to, uint256 amount) public {
        vm.assume(from.code.length == 0 && uint160(from) > 0xffff && from != address(this) && from != address(c) && from != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && from != 0x000000000000000000636F6e736F6c652e6c6f67 && from != 0x4e59b44847b379578588920cA78FbF26c0B4956C && from != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(from, to, amount);
    }

    receive() external payable {}
}
